package com.learnknow.usage;
import jakarta.persistence.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@SpringBootApplication public class UsageServiceApplication{public static void main(String[]a){SpringApplication.run(UsageServiceApplication.class,a);}@Entity public static class Progress{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long userId;public Long courseId;public Long moduleId;public double completionPercent;public Instant updatedAt=Instant.now();}@Entity public static class UsageHistory{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long userId;public Long resourceId;public String action;public Instant timestamp=Instant.now();}@org.springframework.stereotype.Repository public interface ProgressRepo extends JpaRepository<Progress,Long>{Optional<Progress>findByUserIdAndCourseId(Long u,Long c);}@org.springframework.stereotype.Repository public interface HistoryRepo extends JpaRepository<UsageHistory,Long>{List<UsageHistory>findByUserIdOrderByTimestampDesc(Long u);}public record Activity(Long userId,Long resourceId,String action){}public record ProgressRequest(Long userId,Long courseId,Long moduleId,Double completionPercent){}@RestController @RequestMapping("/api/usage")public static class Controller{final ProgressRepository p;final HistoryRepository h;Controller(ProgressRepository p,HistoryRepository h){this.p=p;this.h=h;}@PostMapping("/activity")UsageHistory activity(@RequestBody Activity r){UsageHistory x=new UsageHistory();x.userId=r.userId();x.resourceId=r.resourceId();x.action=r.action();return h.save(x);}@GetMapping("/history/{userId}")List<UsageHistory>history(@PathVariable Long userId){return h.findByUserIdOrderByTimestampDesc(userId);}@PostMapping("/progress")Progress progress(@RequestBody ProgressRequest r){if(r.completionPercent()==null||r.completionPercent()<0||r.completionPercent()>100)throw new IllegalArgumentException("completionPercent must be between 0 and 100");Progress x=p.findByUserIdAndCourseId(r.userId(),r.courseId()).orElseGet(Progress::new);x.userId=r.userId();x.courseId=r.courseId();x.moduleId=r.moduleId();x.completionPercent=r.completionPercent();x.updatedAt=Instant.now();return p.save(x);}@GetMapping("/progress/{userId}/{courseId}")Progress get(@PathVariable Long userId,@PathVariable Long courseId){return p.findByUserIdAndCourseId(userId,courseId).orElseThrow(()->new NoSuchElementException("Progress not found"));}}}
